import { runtimeAlias } from "../analyzer/util.ts";
import {
  assertNever,
  type ChildIR,
  type ExprIR,
  type IRModule,
  type PropIR,
  type FunctionIR,
  isHandlerHook,
  type StateIR,
  type TypeIR,
  walkExpr,
  walkFunction,
} from "../ir/types.ts";
import { exportedComponents, moduleSchemas } from "../prefabs/prefabs.ts";
import { ElementEmitter, colliderTag } from "./elements.ts";
import { RenderGuard } from "./expressions.ts";
import { ROOT, findChildrenSlot, typeText, pending, pendingRef, propertyKey, access, mutableObject } from "./helpers.ts";
import { CodeWriter, sourceMap, type LineOrigin } from "./writer.ts";

/** Built-ins whose `name` a component root takes from the component when it does not write one (`Game` extends `Entity`). */
const NAMED_ROOTS: ReadonlySet<string> = new Set(["Entity", "Game"]);

export interface GeneratorOptions {
  /** Module specifier the generated code imports runtime classes from. */
  readonly runtimeModule: string;
  /** Runtime functions handler code may call (imported from `runtimeModule`). */
  readonly runtimeFunctions: ReadonlySet<string>;
  /** Props each built-in's constructor requires (the runtime manifest's `intrinsicRequired`). */
  readonly requiredHostProps: Readonly<Record<string, readonly string[]>>;
  /** Hooks each built-in implements itself (the runtime manifest's `intrinsicHooks`): a component rooted at one calls `super` first. */
  readonly intrinsicHooks: Readonly<Record<string, readonly string[]>>;
  /**
   * The project's game state, for a module whose components read or act on it: the exported name and where to import it
   * from (relative to the generated file).
   */
  readonly gameState?: { readonly name: string; readonly importFrom: string };
  /** The path from the generated files to the source folder, so `./transitions.ts` becomes `../src/transitions.ts`. Default `".."` + `/`: see `Compiler`. */
  readonly sourceFromOutput?: string;
  /** The generated `tilemaps.ts`, imported for its registration by a module that draws a `<Tilemap>` (see `Compiler.setTilemapsModule`). */
  readonly tilemapsModule?: string;
}

/** Where a generated module's source map points: the generated file's name and the source's path from it. */
export interface SourceMapOptions {
  /** The generated file's name (`Player.ts`), the map's `file`. */
  readonly file: string;
  /** The source as the map names it, relative to the generated file (`../src/Player.tsx`). */
  readonly source: string;
  /** The source text, embedded in the map (`sourcesContent`) so a debugger needs no file. Null leaves it out. */
  readonly sourceContent: string | null;
}

/**
 * IR → TypeScript. Emits one class per component:
 *
 * - state            → typed instance fields
 * - static children  → `readonly` fields, constructed once and attached in the constructor
 * - conditional      → nullable fields, created/destroyed in `render()` via queued structure ops
 * - dynamic props    → assignments to the existing child instance in `render()`
 * - setters          → update the field and `markDirty()`
 */
export function generateModule(module: IRModule, options: GeneratorOptions): string {
  return writeModule(module, options).toString();
}

/**
 * `generateModule`, with a source map (version 3) from each generated line to the component, hook or element it was written
 * for. The code ends with a `//# sourceMappingURL=` comment naming `<file>.map`, where the caller writes `map`.
 */
export function generateModuleWithMap(
  module: IRModule,
  options: GeneratorOptions,
  map: SourceMapOptions
): { readonly code: string; readonly map: string; readonly origins: readonly LineOrigin[] } {
  const w = writeModule(module, options);
  return {
    code: `${w.toString()}//# sourceMappingURL=${map.file}.map\n`,
    map: sourceMap(w.origins, map.file, map.source, map.sourceContent),
    origins: w.origins,
  };
}

/** The generated code, and for each generated line written for a construct of the source, where that construct is. */
export function generateModuleWithOrigins(
  module: IRModule,
  options: GeneratorOptions
): { readonly code: string; readonly origins: readonly LineOrigin[] } {
  const w = writeModule(module, options);
  return { code: w.toString(), origins: w.origins };
}

function writeModule(module: IRModule, options: GeneratorOptions): CodeWriter {
  const w = new CodeWriter();
  w.line(`// Generated by @tsengine/compiler from ${module.sourceFile}. Do not edit.`);

  const usage = { store: false, plain: new Set<string>() };
  const imports = collectImports(module, options.runtimeFunctions, usage, options.intrinsicHooks);
  // What the file's own constants and helpers read: a function from a `.ts` file, a runtime function.
  for (const declaration of module.moduleDeclarations) {
    for (const name of declaration.reads) {
      if (module.plainImports.some((i) => i.name === name)) usage.plain.add(name);
      if (options.runtimeFunctions.has(name) && !imports.includes(name)) imports.push(name);
    }
  }
  // A runtime function whose name the file uses for something of its own (a function from a `.ts` file, a top-level helper) is
  // imported under `runtimeAlias`, and the components call it by that name: the compiler adds calls of its own (`textOf` around
  // the text of a `<Text>`), and an inlined hook calls the functions it imports.
  const own = new Set([...module.plainImports.map((i) => i.name), ...module.moduleDeclarations.map((d) => d.name)]);
  const renamed = new Set(imports.filter((name) => options.runtimeFunctions.has(name) && own.has(name)));
  // What a top-level helper calls a runtime function by, when the file imported it under another name.
  for (const alias of module.runtimeAliases ?? []) {
    if (module.moduleDeclarations.some((d) => d.reads.includes(alias.name)) && !imports.includes(`${alias.importedName} as ${alias.name}`))
      imports.push(`${alias.importedName} as ${alias.name}`);
  }
  if (imports.length > 0) {
    const specifiers = imports.map((name) => (renamed.has(name) ? `${name} as ${runtimeAlias(name)}` : name));
    w.line(`import { ${specifiers.join(", ")} } from ${JSON.stringify(options.runtimeModule)};`);
  }
  if (options.tilemapsModule !== undefined && imports.includes("Tilemap")) w.line(`import ${JSON.stringify(options.tilemapsModule)};`);
  if (usage.store) {
    if (!options.gameState) throw new Error("A component uses the game state, but the generator was given none.");
    w.line(`import { ${options.gameState.name} } from ${JSON.stringify(options.gameState.importFrom)};`);
  }
  const byModule = new Map<string, string[]>();
  const from = options.sourceFromOutput ?? "..";
  const fromOutput = (specifier: string): string => JSON.stringify(`${from}/${specifier.replace(/^\.\//, "")}`);
  for (const i of module.plainImports) {
    if (!usage.plain.has(i.name)) continue;
    if (i.namespace === true) w.line(`import * as ${i.name} from ${fromOutput(i.module)};`);
    else (byModule.get(i.module) ?? byModule.set(i.module, []).get(i.module)!).push(i.name);
  }
  for (const [specifier, names] of byModule) w.line(`import { ${names.join(", ")} } from ${fromOutput(specifier)};`);
  for (const line of typeImportLines(module, options.sourceFromOutput ?? "..")) w.line(line);
  for (const [specifier, { defaultName, names }] of collectComponentImports(module)) {
    const clause = [defaultName, names.length > 0 ? `{ ${names.join(", ")} }` : null].filter((part) => part !== null).join(", ");
    w.line(`import ${clause} from ${JSON.stringify(specifier)};`);
  }
  for (const declaration of module.typeDeclarations) {
    w.blank();
    w.line(`export ${declaration.text}`);
  }
  for (const declaration of module.moduleDeclarations) {
    w.blank();
    for (const line of declaration.text.split("\n")) w.line(line);
  }
  let usesAssume = false;
  let usesKeyIndex = false;
  for (const component of module.components) {
    w.blank();
    w.at(component.span, () => {
      const generator = new ComponentGenerator(
        component,
        w,
        options.requiredHostProps,
        options.intrinsicHooks,
        options.gameState?.name ?? "",
        renamed
      );
      generator.emit();
      usesAssume ||= generator.usesAssume;
      usesKeyIndex ||= generator.usesKeyIndex;
    });
    if (component.isDefaultExport) {
      w.blank();
      w.line(`export default ${component.name};`);
    }
  }
  if (usesAssume) {
    w.blank();
    w.line(
      "/** Narrows for TypeScript what a callback made under a condition reads (the condition held when it was made). It checks nothing. */"
    );
    w.line("function $assume(_condition: unknown): asserts _condition {}");
  }
  if (usesKeyIndex) {
    w.blank();
    for (const line of KEY_INDEX.split("\n")) w.line(line);
  }
  emitPrefabs(module, w);
  return w;
}

/**
 * `import type { Tower } from "../src/rules/battle.ts"` for each type imported from a `.ts` file that the generated module names:
 * in a copied declaration, or a type the IR carries (state, refs, locals). Only names in type text count, not in strings or comments.
 */
function typeImportLines(module: IRModule, from: string): string[] {
  const used = identifiersIn(typeTexts(module));
  const typesByModule = new Map<string, string[]>();
  for (const i of module.typeImports) {
    if (!used.has(i.name)) continue;
    (typesByModule.get(i.module) ?? typesByModule.set(i.module, []).get(i.module)!).push(
      i.importedName !== undefined ? `${i.importedName} as ${i.name}` : i.name
    );
  }
  return [...typesByModule].map(
    ([specifier, names]) => `import type { ${names.join(", ")} } from ${JSON.stringify(`${from}/${specifier.replace(/^\.\//, "")}`)};`
  );
}

/** Every piece of type text the generated module can contain: copied declarations, and the source types in the IR. */
function typeTexts(module: IRModule): string[] {
  const out = [...module.typeDeclarations.map((d) => d.text), ...module.moduleDeclarations.map((d) => d.text)];
  const type = (t: TypeIR): void => {
    if (t.kind === "SourceType") out.push(t.text);
    else if (t.kind === "Array") type(t.element);
  };
  const fn = (f: FunctionIR): void => {
    f.params.forEach((p) => type(p.type));
    walkFunction(
      f,
      (e) => {
        if (e.kind === "Arrow") e.params.forEach((p) => type(p.type));
        if (e.kind === "Callback") fn(e.fn); // its own `let` types
      },
      (stmt) => {
        if (stmt.kind === "LocalConst" && stmt.type) type(stmt.type);
      }
    );
  };
  const children = (list: readonly ChildIR[]): void => {
    for (const child of list) {
      if (child.kind === "ChildrenSlot") continue;
      for (const el of [child.element, ...(child.kind === "KeyedListChild" && child.alternate ? [child.alternate] : [])]) {
        for (const p of el.props) if (p.kind === "CallbackProp") fn(p.handler);
        children(el.children);
      }
    }
  };
  for (const c of module.components) {
    c.state.forEach((s) => type(s.type));
    for (const p of c.props) if (p.type.kind === "SourceText") out.push(p.type.text);
    for (const hook of c.hooks) if (isHandlerHook(hook)) fn(hook.handler);
    for (const own of c.functions) fn(own.fn);
    for (const p of c.root.props) if (p.kind === "CallbackProp") fn(p.handler);
    children(c.root.children);
  }
  return out;
}

/** The identifiers in some TypeScript text, outside string literals and comments. */
function identifiersIn(texts: readonly string[]): Set<string> {
  const names = new Set<string>();
  for (const text of texts) {
    const code = text.replace(/\/\*[\s\S]*?\*\/|\/\/[^\n]*|"(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|`(?:\\.|[^`\\])*`/g, " ");
    for (const match of code.matchAll(/[A-Za-z_$][A-Za-z0-9_$]*/g)) names.add(match[0]);
  }
  return names;
}

/**
 * `export const prefabs = { Enemy: { create, props } }` for the exported
 * components: the data a scene needs to place them. `ConstructorParameters`
 * types `create`, so the props interface need not be exported.
 */
function emitPrefabs(module: IRModule, w: CodeWriter): void {
  const exported = exportedComponents(module);
  if (exported.length === 0) return;
  const schemas = new Map(moduleSchemas(module).map((s) => [s.name, s] as const));
  w.blank();
  w.open("export const prefabs = {");
  for (const component of exported) {
    w.open(`${component.name}: {`);
    w.line(
      component.propsType
        ? `create: (props: ConstructorParameters<typeof ${component.name}>[0]) => new ${component.name}(props),`
        : `create: () => new ${component.name}(),`
    );
    const props = schemas.get(component.name)!.props;
    if (props.length === 0) w.line("props: [],");
    else {
      w.open("props: [");
      for (const prop of props) w.line(`${JSON.stringify(prop)},`);
      w.close("],");
    }
    w.close("},");
  }
  w.close("} satisfies Record<string, PrefabDefinition>;");
}

/** Runtime values (intrinsic classes, helper functions) and types the module's output refers to. */
function collectImports(
  module: IRModule,
  runtimeFunctions: ReadonlySet<string>,
  usage: { store: boolean; plain: Set<string> },
  intrinsicHooks: Readonly<Record<string, readonly string[]>> | undefined
): string[] {
  const values = new Set<string>();
  const types = new Set<string>();
  const visitType = (type: TypeIR): void => {
    if (type.kind === "Named") types.add(type.name);
  };
  const onExpr = (e: ExprIR): void => {
    if (e.kind === "Call" && e.callee.kind === "Function" && runtimeFunctions.has(e.callee.name)) values.add(e.callee.name);
    if ((e.kind === "Call" && e.callee.kind === "Action") || e.kind === "ActionRef") usage.store = true;
    if (e.kind === "PlainRef") usage.plain.add(e.name);
    if (e.kind === "Call" && e.callee.kind === "Plain") usage.plain.add(e.callee.name.split(".")[0]!);
  };
  const visitExpr = (expr: ExprIR): void => walkExpr(expr, onExpr);
  const visitProps = (props: readonly PropIR[]): void =>
    props.forEach((p) => {
      if (p.kind === "CallbackProp") visitFunction(p.handler);
      else visitExpr(p.value);
    });
  const visitChildren = (children: readonly ChildIR[]): void => {
    for (const child of children) {
      if (child.kind === "ChildrenSlot") continue;
      if (child.element.component.kind === "Intrinsic") values.add(child.element.component.name);
      if (child.kind === "ConditionalChild") visitExpr(child.condition);
      if (child.kind === "KeyedListChild") {
        visitExpr(child.source);
        visitExpr(child.key);
        if (child.condition) visitExpr(child.condition);
        if (child.alternate) {
          if (child.alternate.component.kind === "Intrinsic") values.add(child.alternate.component.name);
          visitProps(child.alternate.props);
          visitProps(child.alternate.transform);
        }
      }
      visitProps(child.element.props);
      visitProps(child.element.transform);
      visitChildren(child.element.children);
    }
  };
  const visitFunction = (fn: FunctionIR): void => {
    fn.params.forEach((p) => visitType(p.type));
    walkFunction(fn, onExpr, (stmt) => {
      if (stmt.kind === "CallAction") usage.store = true;
    });
  };
  if (exportedComponents(module).length > 0) types.add("PrefabDefinition");
  for (const c of module.components) {
    if (c.acceptsChildren) types.add("Child");
    // A text wrapper's props (`children: TextChild | readonly TextChild[]`) name the type in the copied props interface.
    if (c.props.some((p) => p.name === "children" && p.type.kind === "SourceText" && /\bTextChild\b/.test(p.type.text)))
      types.add("TextChild");
    values.add(c.root.component.name);
    visitProps(c.root.props);
    visitProps(c.root.transform);
    visitChildren(c.root.children);
    c.props.forEach((p) => p.defaultValue && visitExpr(p.defaultValue)); // a default may call a runtime function (`speed = clamp(5, 0, 3)`)
    c.state.forEach((s) => {
      visitExpr(s.initialValue);
      if (s.globalKey !== undefined) usage.store = true;
    });
    if (c.sounds.length > 0) values.add("Sound");
    for (const hook of c.hooks) if (isHandlerHook(hook)) visitFunction(hook.handler);
    for (const own of c.functions) visitFunction(own.fn);
    // The `onUpdate` override that calls `super` or several handlers is written with every parameter the runtime passes, `input` too.
    const updates = c.hooks.filter((h) => isHandlerHook(h) && h.kind === "OnUpdate").length;
    if ((intrinsicHooks?.[c.root.component.name] ?? []).includes("onUpdate") && updates > 0) types.add("InputState");
  }
  return [...[...values].sort(), ...[...types].sort().map((t) => `type ${t}`)];
}

/** Components imported from other source files, grouped by the specifier of their generated module (`.tsx` → `.ts`). */
function collectComponentImports(module: IRModule): Map<string, { defaultName: string | null; names: string[] }> {
  const named = new Map<string, Set<string>>();
  const defaults = new Map<string, string>();
  const visit = (children: readonly ChildIR[]): void => {
    for (const child of children) {
      if (child.kind === "ChildrenSlot") continue;
      for (const ref of [
        child.element.component,
        ...(child.kind === "KeyedListChild" && child.alternate ? [child.alternate.component] : []),
      ]) {
        if (ref.kind === "Imported") {
          const specifier = ref.module.replace(/\.tsx$/, ".ts");
          if (!named.has(specifier)) named.set(specifier, new Set());
          if (ref.isDefault) defaults.set(specifier, ref.name);
          else named.get(specifier)!.add(ref.name);
        }
      }
      visit(child.element.children);
    }
  };
  for (const c of module.components) visit(c.root.children);
  return new Map(
    [...named]
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([specifier, names]) => [specifier, { defaultName: defaults.get(specifier) ?? null, names: [...names].sort() }])
  );
}

/** The component generator: each layer in its own file (expressions, handlers, elements), each extending the one before it. */
class ComponentGenerator extends ElementEmitter {
  emit(): void {
    const c = this.c;
    const w = this.w;
    const hasRender = this.hostHasDynamicProps() || this.childrenNeedRender(c.root.children);

    // A component with props passes them (and its defaults) up to the runtime host, which owns `this.props`.
    // `children` is not a runtime prop: the parent mounts elements at the `{children}` slot instead.
    const runtimeProps = c.propsType && c.acceptsChildren ? `Omit<${c.propsType}, "children">` : c.propsType;
    // A `<Collider tag="foe">` root passes its tag on too, so `onReceive`'s value is typed by it (`ColliderMessages`).
    const tag = colliderTag(c.root);
    const extendsClause =
      tag !== null
        ? `${c.root.component.name}<${runtimeProps ?? "{}"}, ${tag}>`
        : runtimeProps
          ? `${c.root.component.name}<${runtimeProps}>`
          : c.root.component.name;
    w.block(`export class ${c.name} extends ${extendsClause}`, () => {
      // What a compiled component draws changes only in its constructor, its `render()` and structural changes, which the
      // runtime reports; its hooks only call setters. So the player may reuse its draw records while it stands still (see `FrameBuilder`).
      w.line("static readonly managed = true;");
      // Its `render()` writes only what differs and says what it wrote to (`markMoved`, `markChanged`), so the runtime does not
      // take every render for a change: the player keeps what it drew for a render that changed nothing, and for one that only moved it.
      w.line("protected override readonly reportsChanges = true;");
      // Its root was another component or a condition: layout sees through it to what it holds.
      if (c.root.layoutContents) w.line("override readonly layoutContents = true;");
      // Persistent state.
      for (const s of c.state) {
        if (s.globalKey !== undefined) {
          // A snapshot of the game's value (the store is the truth); refreshed in `commitState` when the leaf changes.
          w.line(`${s.name}: ${typeText(s.type)} = ${this.storeName}.store.get<${typeText(s.type)}>(${JSON.stringify(s.globalKey)});`);
          continue;
        }
        w.line(`${s.name}: ${typeText(s.type)} = ${this.expr(s.initialValue, true)};`);
        // The value setters write; it becomes `s.name` when the component next renders.
        if (this.hasSetter(s.id)) w.line(`${pending(s)}: ${typeText(s.type)} = this.${s.name};`);
      }
      // A `useMutable` is stored a field at a time (`$s_vx`); its view reads and writes them as the source does, `component.s.vx`,
      // for tests and tools: a read is the committed value (what render saw), a write goes through the field's setter, so it renders
      // as a handler's write would. Made the first time it is asked for, so it costs nothing otherwise.
      const mutables = new Map<string, StateIR[]>();
      for (const s of c.state) {
        if (s.mutable === undefined) continue;
        mutables.set(s.mutable.view, [...(mutables.get(s.mutable.view) ?? []), s]);
      }
      const mutableObjectLines = new Map<string, string[]>();
      for (const [view, fields] of mutables) {
        const type = `{ ${fields.map((f) => `${propertyKey(f.mutable!.field)}: ${typeText(f.type)}`).join("; ")} }`;
        const cache = `#${view}View`;
        const members = fields.map(
          (f) =>
            `get ${propertyKey(f.mutable!.field)}() { return self.${f.name}; }, set ${propertyKey(f.mutable!.field)}(value: ${typeText(f.type)}) { self.${this.setter(f.id)}(value); }`
        );
        w.line(`${cache}: ${type} | undefined;`);
        w.line(`get ${view}(): ${type} { const self = this; return (this.${cache} ??= { ${members.join(", ")} }); }`);
        // The object a handler hands over when it passes the `useMutable` whole (`takeHit(s)`), written once the class body is (only a
        // `useMutable` some handler passes whole gets one): one per component, made the first time it is passed. Its fields are the
        // component's as a handler sees them: a read is the value as it is now, a write goes through the field's setter (so it renders,
        // as `s.hp -= 1` would). Once the component has been unmounted a write does nothing (`$mayWrite`).
        const live = fields.map((f) => {
          const key = propertyKey(f.mutable!.field);
          const path = `${f.mutable!.name}.${f.mutable!.field}`;
          return `get ${key}() { return self.${pending(f)}; }, set ${key}(value: ${typeText(f.type)}) { if (self.$mayWrite(${JSON.stringify(path)})) self.${this.setter(f.id)}(value); }`;
        });
        const objectCache = `${mutableObject(view)}Cache`;
        mutableObjectLines.set(view, [
          `${objectCache}: ${type} | undefined;`,
          `get ${mutableObject(view)}(): ${type} { const self = this; return (this.${objectCache} ??= { ${live.join(", ")} }); }`,
        ]);
      }
      const mutableObjectsAt = w.mark();
      // Its value props as a handler reads them (`this.$live_hp`): what its parent has now (see `GameObject.liveProp`). A property, not a
      // call, so TypeScript narrows it (`tower !== null && …`) as it does `this.props.tower`; and a getter of the class for each prop, not
      // one object of getters, which cost a crowd about as much again as the read itself (games/swarm/DESIGN.md).
      if (runtimeProps) for (const p of c.props) if (p.role === "value") w.line(liveGetter(p.name, runtimeProps));
      // The paths it reads: the runtime tells it when one changes (see `GameObject.gameStateKeys`).
      const globals = c.state.filter((s) => s.globalKey !== undefined);
      if (globals.length > 0) {
        w.line(`override readonly gameStateStore = ${this.storeName}.store;`);
        w.line(
          `override readonly gameStateKeys: readonly string[] = [${[...new Set(globals.map((s) => JSON.stringify(s.globalKey)))].join(", ")}];`
        );
      }
      // Per-instance objects a factory made: told when the component joins and leaves a world (a body learns its world so).
      const handles = c.state.filter((s) => s.handle);
      if (handles.length > 0)
        w.line(`protected override ownedHandles(): readonly unknown[] { return [${handles.map((s) => `this.${s.name}`).join(", ")}]; }`);
      // Sounds: one per useSound. Playing is an effect, so nothing is marked dirty.
      for (const s of c.sounds) {
        w.line(`readonly ${s.name}: Sound = new Sound(${JSON.stringify(s.path)});`);
      }
      // Functions declared in the body: arrows in fields, before the children that may be handed them (`onPress={handleHit}`).
      for (const f of c.functions) w.line(`readonly ${f.name} = ${this.callback(f.fn)};`);
      // Persistent children (field initialisers run after state initialisers, so they can read state).
      this.emitElementFields(c.root.children, "persistent");

      w.blank();
      const defaults = c.props.filter((p) => p.defaultValue !== null);
      const defaultsObject =
        defaults.length > 0 ? `{ ${defaults.map((p) => `${propertyKey(p.name)}: ${this.expr(p.defaultValue!, true)}`).join(", ")} }` : null;
      // Every prop optional: the parent may omit the object entirely.
      const constructorParams = runtimeProps ? `props: ${runtimeProps}${c.props.every((p) => p.optional) ? " = {}" : ""}` : "";
      w.block(`constructor(${constructorParams})`, () => {
        const staticHostProps = c.root.props.filter((p) => p.kind === "StaticProp");
        // A built-in's constructor may require a prop (a Sprite's `image`) that is dynamic here. `super()` runs before
        // state exists, so it gets a placeholder and its real value in the first `render()`, which the constructor runs.
        const required = this.requiredHostProps[c.root.component.name] ?? [];
        const placeholders = c.root.props.flatMap((p) =>
          p.kind === "DynamicProp" && required.includes(p.name) ? [`${propertyKey(p.name)}: undefined as never`] : []
        );
        // A root `<Entity>` (or `<Game>`, a fragment, or the container a component or condition root is held in) with no
        // `name` of its own is named after the component, as `<Entity name="Player">` would: what `other.owner` reads.
        const defaultName =
          c.root.component.kind === "Intrinsic" &&
          NAMED_ROOTS.has(c.root.component.name) &&
          !c.root.props.some((p) => "name" in p && p.name === "name")
            ? [`name: ${JSON.stringify(c.name)}`]
            : [];
        const hostEntries = this.within({ inlineMemos: true }, () => [
          ...defaultName,
          ...staticHostProps.map((p) => `${propertyKey(p.name)}: ${this.expr(p.value, true)}`),
          ...placeholders,
        ]);
        const host = hostEntries.length > 0 ? `{ ${hostEntries.join(", ")} }` : "{}";
        if (c.propsType) w.line(`super(${host}, props${defaultsObject ? `, ${defaultsObject}` : ""});`);
        else w.line(hostEntries.length > 0 ? `super(${host});` : "super();");
        // A callback on the root (`<Collider onCollisionEnter>`) is assigned after `super()`: an arrow that uses
        // `this` cannot be created inside the call to it.
        for (const p of c.root.props) {
          if (p.kind === "CallbackProp") w.line(`this.${p.name} = ${this.callback(p.handler)};`);
        }
        this.emitStaticTransform(c.root.transform, "this");
        this.emitStaticWiring(c.root.children, ROOT);
        const slot = findChildrenSlot(c.root.children, "this");
        if (slot) {
          if ("forward" in slot) {
            // The children this component is given are passed on, whole, to the component that renders them.
            w.line(`this.passedChildrenForward = ${slot.forward};`);
            if (slot.at !== 0) w.line(`this.passedChildrenForwardAt = ${slot.at};`);
          } else {
            // Where a parent's children mount: the container holding `{children}`, and the slot's position among its children.
            w.line(`this.passedChildrenHost = ${slot.host};`);
            w.line(`this.passedChildrenSlot = ${slot.index};`);
          }
        }
        if (hasRender) {
          w.line("this.render();");
          w.line("this.commitStructure();");
        }
      });

      if (c.propsType) {
        w.blank();
        w.block(`updateProps(next: Partial<${runtimeProps}>): void`, () => {
          w.line(`if (this.applyProps(next${defaultsObject ? `, ${defaultsObject}` : ""})) this.markDirty();`);
        });
      }

      for (const hook of c.hooks) {
        switch (hook.kind) {
          case "StateSlot": {
            if (hook.setterName === null) break;
            const s = this.state(hook.state);
            const type = typeText(s.type);
            w.blank();
            // A write: the next value, which a handler reads back at once and render sees once committed. Only a different value
            // (`===`) renders.
            w.at(hook.span, () =>
              w.block(`${hook.setterName}(value: ${type}): void`, () => {
                w.line(`if (value === ${pendingRef(s)}) return;`);
                w.line(`${pendingRef(s)} = value;`);
                w.line("this.markDirty();");
              })
            );
            break;
          }
          case "OnUpdate":
          case "OnInput":
          case "OnMount":
          case "OnUnmount":
            break; // emitted below, grouped by kind
          default:
            assertNever(hook, "hook");
        }
      }

      const settable = c.state.filter((s) => s.globalKey === undefined && this.hasSetter(s.id));
      const shared = c.state.filter((s) => s.globalKey !== undefined);
      const refreshed = c.state.filter((s) => s.refresh !== undefined);
      if (settable.length > 0 || shared.length > 0 || refreshed.length > 0) {
        w.blank();
        w.block("override commitState(): void", () => {
          for (const s of settable) w.line(`this.${s.name} = ${pendingRef(s)};`);
          // Every component that reads a leaf refreshes its snapshot when the game changes it, whoever acted.
          for (const s of shared)
            w.line(`this.${s.name} = ${this.storeName}.store.get<${typeText(s.type)}>(${JSON.stringify(s.globalKey)});`);
          // A context's value, read again from its reader (the provider marked this component dirty when it changed).
          for (const s of refreshed) w.line(`this.${s.name} = ${this.expr(s.refresh!, true)};`);
        });
      }

      // Hot reload: the component's own state, by their stable ids, so a rebuilt tree can take them back
      // (see `captureHotState` in the runtime). A value whose type no longer matches is skipped.
      const local = c.state.filter((s) => s.globalKey === undefined && !s.transient);
      if (local.length > 0) {
        w.blank();
        w.block("override saveHotState(): Record<string, unknown>", () => {
          const entries = [...local.map((s) => `${JSON.stringify(s.id)}: ${this.hasSetter(s.id) ? pendingRef(s) : `this.${s.name}`}`)];
          w.line(`return { ${entries.join(", ")} };`);
        });
        w.blank();
        w.block("override loadHotState(saved: Record<string, unknown>): void", () => {
          w.line("let value: unknown;");
          for (const s of local) {
            const target = this.hasSetter(s.id) ? pendingRef(s) : `this.${s.name}`;
            w.line(`value = saved[${JSON.stringify(s.id)}];`);
            w.line(`if (this.hotFits(value, ${target})) ${target} = value as ${typeText(s.type)};`);
          }
          // A setter's value reaches its field, and a field's value reaches what is drawn, on the next render.
          if (hasRender || settable.length > 0) w.line("this.markDirty();");
        });
      }

      this.emitHandlerMethods();

      if (hasRender) {
        w.blank();
        const fields = w.mark();
        let inputs: readonly string[] = [];
        w.block("override render(): void", () =>
          w.at(c.root.span, () => {
            this.renderTemps = 0;
            const prologue = w.mark();
            // A memo read where the render always writes is worked out once, at the top, rather than at each place it is read.
            const renderMemos = new Map<string, string>();
            const memoLines: string[] = [];
            for (const memo of this.alwaysReadMemos()) {
              const local = `$r${renderMemos.size}`;
              memoLines.push(`const ${local} = ${this.within({ renderMemos }, () => this.expr(memo, true))};`);
              renderMemos.set(memo.key, local);
            }
            const body = (guard: RenderGuard | null): void => {
              this.renderTemps = 0;
              this.within({ renderMemos, guard }, () => {
                const dynamic = c.root.props.filter((p) => p.kind === "DynamicProp");
                this.emitReportedWrites(
                  dynamic.map((prop) => ({
                    target: access("this", prop.name),
                    value: prop.value,
                    type: `${c.name}[${JSON.stringify(prop.name)}]`,
                  })),
                  "this.markChanged()"
                );
                this.emitDynamicTransform(c.root.transform, "this");
                this.emitChildUpdates(c.root.children, ROOT, "persistent");
              });
            };
            const guard = new RenderGuard();
            body(guard);
            if (guard.useful) inputs = guard.inputs;
            else {
              // Nothing would be skipped: write the render again without guards.
              w.truncate(prologue);
              body(null);
            }
            // The dirty mask: a bit for each input a guarded part reads that is not what it was at the last render (all of them the first time).
            const maskLines =
              inputs.length === 0
                ? []
                : [
                    "const $i = this.$in;",
                    "let $d = 0;",
                    ...inputs.map((input, bit) => `if ($i[${bit}] !== ${input}) { $i[${bit}] = ${input}; $d |= ${1 << bit}; }`),
                  ];
            w.insert(prologue, [...memoLines, ...maskLines]);
          })
        );
        // What each input was at the last render; a fresh object at first, which no input can be.
        if (inputs.length > 0) w.insert(fields, [`readonly $in: unknown[] = new Array(${inputs.length}).fill({});`, ""]);
      }
      // Last, once every handler has been written: an object only for a `useMutable` one of them passes whole. Inserted above
      // everything after `mutableObjectsAt`, so the marks written later were already used.
      w.insert(
        mutableObjectsAt,
        [...mutableObjectLines].filter(([view]) => this.mutableObjects.has(view)).flatMap(([, lines]) => lines)
      );
    });
  }
}

/**
 * A prop as a handler reads it (`this.$live_hp`): what `GameObject.liveProp` does, with the parent's getter read by its name.
 * `liveProp` takes the name as a value and is one function for every component and every prop, so its read of `getters[name]` and
 * its call are of whatever came last; here each is of one prop of one component, which the engine under it can settle on. A parent
 * that gave no getter for this prop (none at all, or only `$all` for a spread) is left to `liveProp`.
 */
function liveGetter(name: string, props: string): string {
  const key = JSON.stringify(name);
  return `get $live_${name}(): ${props}[${key}] { const $own = this.propGetters?.[${key}]; if ($own === undefined) return this.liveProp(${key}); const $value = $own(); return ($value !== undefined ? $value : this.props[${key}]) as ${props}[${key}]; }`;
}

/**
 * What a list item's prop getter finds its item by: the index of the first item whose key is `key`, from a map of the list's keys
 * made the first time this array is asked about for this key expression (`site`), so each read is a lookup and not a search. A list
 * field is replaced, never changed, when it changes, so the map stays right for its array; the item found is still checked, and a
 * miss or a mismatch (an array a helper changed in place) is searched as `findIndex` would.
 */
const KEY_INDEX = `/** The index of the item with this key, from a map of the array's keys made once per array (see the compiler's \`KEY_INDEX\`). */
const $keyIndexes = new WeakMap<readonly unknown[], Map<string, Map<unknown, number>>>();
function $indexOfKey<T>(list: readonly T[], site: string, key: unknown, keyOf: (item: T, index: number) => unknown): number {
  let sites = $keyIndexes.get(list);
  if (sites === undefined) $keyIndexes.set(list, (sites = new Map()));
  let index = sites.get(site);
  if (index === undefined) {
    index = new Map();
    for (let i = 0; i < list.length; i++) {
      const k = keyOf(list[i]!, i);
      if (!index.has(k)) index.set(k, i);
    }
    sites.set(site, index);
  }
  const i = index.get(key);
  if (i !== undefined && i < list.length && keyOf(list[i]!, i) === key) return i;
  return list.findIndex((item, n) => keyOf(item, n) === key);
}`;
